[8069]={["atomIDs"]={"8069:description:1-62","8069:description:65-173","8069:description:176-275","8069:description:278-344","8069:description:349-392","8069:description:394-448","8069:description:451-496","8069:objective:1-55","8069:objective:58-146","8069:objective:151-221"},["opening"]="Legend said the ancient illusionist robes never looked the same twice. Al'tabim treated fine cloth interwoven with mojo as a sign of station, requiring a Primal Hakkari Kossack and Revered standing for his offering.",["pending"]="{actor} meant to recover a Primal Hakkari Kossack for Al'tabim's illusionist offering.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} fulfilled Al'tabim's Primal Hakkari Kossack turn-in for the illusionist offering.",["sourceClassMask"]="128",["sourceHash"]="322614b52d92d86dc9b9b291623a50ca4981427c1f94fdbdf4b230be21ba3109",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
