[8071]={["atomIDs"]={"8071:description:1-106","8071:description:109-212","8071:description:215-338","8071:description:343-500","8071:objective:1-53","8071:objective:56-144","8071:objective:149-219"},["opening"]="The confessors' distinctive mantles marked them as preservers and aided their judgment through mojo. Al'tabim offered one in exchange for a Primal Hakkari Aegis, requiring Revered standing among the tribe.",["pending"]="{actor} intended to bring a Primal Hakkari Aegis to Al'tabim.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} fulfilled Al'tabim's Primal Hakkari Aegis turn-in.",["sourceClassMask"]="16",["sourceHash"]="1d87cdb400b7d05f68e267e9ca3eab42280be29692830939e4a8ef3bb16d4aec",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[8072]={["aftermath"]="Falthir offered the madcap's mantle as recognition among the Zandalar. His praise concerned the tribe's enemies without supplying a personal record of particular battlefield actions.",["atomIDs"]={"8072:description:1-63","8072:description:66-214","8072:description:217-315","8072:description:318-390","8072:description:395-507","8072:objective:1-52","8072:objective:55-143","8072:objective:148-216"},["endingAtomIDs"]={"8072:completion:1-87","8072:completion:90-237"},["opening"]="Falthir told of a legendary madcap whose mantle and twin daggers shrouded a terrifyingly swift form. Madcaps still cherished that garment as a sign of belonging; his offering required a Primal Hakkari Girdle and Honored standing.",["pending"]="{actor} meant to recover a Primal Hakkari Girdle for Falthir.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed Falthir's Primal Hakkari Girdle turn-in.",["sourceClassMask"]="8",["sourceConflicts"]={"Legend names the same figure Khar'vaxal and Kar'xavan; neither spelling promoted as settled identity."},["sourceHash"]="9bd10b24d0c8819ad00dc05522d4f08de9d311f0fdc84fe7a529aeed7ed2a5ae",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
