[8105]={["atomIDs"]={"8105:description:1-72","8105:description:75-197","8105:description:200-270","8105:description:275-375","8105:description:378-431","8105:description:436-492","8105:objective:1-118"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["minimumStage"]=2,["objectiveSummary"]="Assault the mine, lumber mill, blacksmith and farm for Oslight.",["opening"]="Oslight's charge linked holding territory to operating the basin's supply sites. Attacking the enemy's banners at the four distant positions would contest the raw materials needed by the League's forces.",["pending"]="{actor} would assault the four sites specified by Oslight.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} assaulted the four positions and reported to Oslight.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="d4d02a5095cdbf3b61511d7c059ff96d1970a9032438d5e64549ef323ee4686a",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[8114]={["atomIDs"]={"8114:description:1-109","8114:description:112-222","8114:description:227-294","8114:description:297-367","8114:description:370-475","8114:description:480-504","8114:objective:1-127"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["minimumStage"]=2,["objectiveSummary"]="Hold four basin bases together and return to Oslight.",["opening"]="Oslight wanted the League's proven defenders to seize four strategic sites at once. Such a hold would secure critical resources and demonstrate resistance to the Horde's campaign.",["pending"]="{actor} would capture and hold four bases simultaneously.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} held four bases at once and reported to Oslight.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="437f7ba179084d27b7daddebf333ac1671cc3913e33b86fb29f20c4c02374874",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[8115]={["atomIDs"]={"8115:description:1-71","8115:description:74-150","8115:description:155-188","8115:description:193-283","8115:description:286-353","8115:description:358-419","8115:objective:1-104"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["minimumStage"]=2,["objectiveSummary"]="Hold all five basin bases together and report to Oslight.",["opening"]="The League planned a concentrated push to drive the Defilers from every strategic point in the basin. Oslight asked for simultaneous control rather than a succession of isolated assaults.",["pending"]="{actor} would seek control of all five basin bases at once.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} held all five bases simultaneously and returned to Oslight.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="de70ca90f5c00766fc8760c66d405b7f37afe01a3e60392aa184f06e340f2017",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[8120]={["atomIDs"]={"8120:description:1-103","8120:description:106-211","8120:description:214-281","8120:description:286-374","8120:description:377-450","8120:description:464-508","8120:objective:1-118"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["minimumStage"]=2,["objectiveSummary"]="Assault the mine, lumber mill, blacksmith and stables for Dwire.",["opening"]="Dwire opposed the League's advance into Arathi and its claim to the basin's supplies. His order called for enemy banners to be torn down at four strategic sites, asserting Horde control of the disputed ground.",["pending"]="{actor} would assault the four positions named by Dwire.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} assaulted the mine, lumber mill, blacksmith and stables and reported to Dwire.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="928699ab4373de9f4045863586630a0e1e7a117c44b25a730fbd9d9bf644d2bb",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[8121]={["atomIDs"]={"8121:description:1-87","8121:description:90-205","8121:description:210-263","8121:description:266-348","8121:description:351-436","8121:description:441-503","8121:objective:1-101"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["minimumStage"]=2,["objectiveSummary"]="Hold four Arathi Basin bases simultaneously and report to Dwire.",["opening"]="The Defilers wanted to show the League how fragile its hold on Arathi could be. Seizing four strategic positions at once would make that challenge visible across the basin.",["pending"]="{actor} would seek control of four basin bases at the same time.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} held four bases simultaneously and reported to Dwire.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="698c96eafcb17a087da7e52fa045f7ce082c11981ad8c6021360ace3da39be5a",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
