[8195]={["atomIDs"]={"8195:description:1-62","8195:description:183-224","8195:description:227-312","8195:description:315-401","8195:description:404-497","8195:description:65-178"},["objectiveSummary"]="Trade a set of three tribal coins to Vinchaxa.",["opening"]="Vinchaxa sought tribal coins circulating in Zul'Gurub, each bearing its own mojo. Some served his companions' armor work; spare sets could instead be traded for Honor Tokens usable with Rin'wosho.",["pending"]="{actor} planned to present the requested set of three tribal coins to Vinchaxa.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed Vinchaxa's coin-set exchange.",["sourceClassMask"]="?",["sourceHash"]="4e91a719b416a207d6a782bbcafa85443d5258cc02108feea596373b7ea0445b",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[8201]={["aftermath"]="Exzhal judged the channelers' removal to have halted the theft of divine power and weakened Hakkar. The collection struck at the god's support without itself declaring him dead.",["atomIDs"]={"8201:description:1-11","8201:description:14-78","8201:description:81-238","8201:description:241-259","8201:description:264-382","8201:description:387-424","8201:objective:1-96"},["endingAtomIDs"]={"8201:completion:1-21","8201:completion:24-94","8201:completion:99-132","8201:completion:135-224"},["opening"]="Exzhal said Hakkar drew divine energy through enthralled high priests in Zul'Gurub. He supplied a sacred cord for five channelers' heads, making the disruption of that power the purpose of the grim collection.",["pending"]="{actor} would string five Channeler's Heads and return the collection to Exzhal.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the Collection of Troll Heads made from five Channeler's Heads to Exzhal.",["sourceClassMask"]="?",["sourceHash"]="25171bb12282ff9d666d745d5bef97cc5f4434ed05dff19fed359e4c50ab5cce",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[8227]={["atomIDs"]={"8227:description:1-82","8227:description:85-127","8227:description:132-161","8227:objective:1-61"},["opening"]="A rolled silken tape lay among shattered fishing gear. Its label named Nat Pagle in Dustwallow, giving the lost measuring tool a clear owner and destination.",["pending"]="{actor} intended to return Nat's Measuring Tape.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered Nat's Measuring Tape to Nat Pagle in Dustwallow Marsh.",["sourceClassMask"]="?",["sourceHash"]="102200edc73a8e870760317a3ff530821ae5d44cffbecce94514f0084605554d",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[8231]={["atomIDs"]={"8231:description:1-68","8231:description:71-102","8231:description:107-189","8231:description:194-276","8231:objective:1-49","8231:objective:52-114"},["editorialVersion"]=2,["endingAtomIDs"]={"8231:completion:1-84","8231:completion:89-146"},["opening"]="The resilient wavethrasher offers Ogtinc another image of a hunter's strength. Its reflective scales must be sought along Azshara's coast as the next part of the charm.",["pending"]="{actor} would bring Ogtinc six Wavethrasher Scales.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} supplied the scales and earned Ogtinc's approval for a harder hunt.",["sourceHash"]="16ccc0cba70957c65950da1d667c50d62da6399dcdf413ca27d633099f096e75",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[8232]={["atomIDs"]={"8232:description:1-94","8232:description:97-189","8232:description:194-242","8232:description:245-314","8232:description:319-401","8232:description:404-449","8232:objective:1-48","8232:objective:51-113"},["editorialVersion"]=2,["endingAtomIDs"]={"8232:completion:1-92"},["opening"]="Morphaz's tooth represents the strength found in companions. Ogtinc sends the hunter into the Temple of Atal'Hakkar with a warning to find others who share an enemy in the green drake.",["pending"]="{actor} would obtain Morphaz's tooth for Ogtinc.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned the tooth and completed Ogtinc's hunter trial.",["sourceHash"]="0fabe17fba3b10301ca664746dc7adad60a1eb64c00059ff040f706dc8345e3f",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[8233]={["aftermath"]="Jorach explained that he had lost a cherished possession and wanted it recovered at any cost.",["atomIDs"]={"8233:description:1-51","8233:description:54-101","8233:description:106-223","8233:objective:1-54"},["editorialVersion"]=2,["endingAtomIDs"]={"8233:completion:1-26","8233:completion:29-88","8233:completion:93-197","8233:completion:200-255","8233:completion:258-285","8233:completion:290-312","8233:completion:314-343"},["opening"]="Ravenholdt's summons says little beyond the need for a private meeting. A mountain path northwest of Durnholde leads to the manor where Jorach awaits the visitor.",["pending"]="{actor} would meet Lord Jorach at Ravenholdt Manor.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} heard Jorach's request to recover a lost possession.",["sourceHash"]="02112bc7b22836e381bbb49fe380ed72945a84909adde31f0b41cbee25bb0706",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[8234]={["atomIDs"]={"8234:description:1-19","8234:description:22-100","8234:description:105-172","8234:description:175-229","8234:description:231-298","8234:description:301-307","8234:description:312-394","8234:description:396-404","8234:description:407-451","8234:description:454-494","8234:objective:1-67","8234:objective:70-128"},["editorialVersion"]=2,["endingAtomIDs"]={"8234:completion:1-37","8234:completion:39-65"},["opening"]="Jorach's stolen blue bag passed to Timbermaw shamans after the thieves failed to open it. He wants it taken to Xylem once recovered, recommending subtlety over a fight.",["pending"]="{actor} would recover the Sealed Azure Bag and bring it to Xylem.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered Jorach's bag to the archmage.",["sourceHash"]="3e034c15ab27110f4a37d346ea16125e8b5017bbd58bd01471a587aaac7a57c5",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
