[8240]={["aftermath"]="Vinchaxa counted each destroyed bijou as progress against Hakkar's servants. He explained that further offerings at the altar could continue that work.",["atomIDs"]={"8240:description:1-150","8240:description:155-245","8240:description:248-387","8240:description:392-435","8240:objective:1-95","8240:objective:98-135"},["endingAtomIDs"]={"8240:completion:1-12","8240:completion:14-140","8240:completion:143-218","8240:completion:223-304","8240:completion:307-365","8240:completion:368-465"},["opening"]="The Zandalar welcomed outsiders to destroy Hakkari bijous at Zanza's altar. Vinchaxa urged one such offering on Yojamba Isle and asked for a conversation afterward.",["pending"]="{actor} intended to destroy a Hakkari Bijou at the Altar of Zanza and speak with Vinchaxa.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the bijou-destruction assignment and spoke with Vinchaxa.",["sourceClassMask"]="?",["sourceHash"]="81697d369ce558c54274809e1eda714d8e7125f7dbe14779f79b47810a7ef4a1",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
