[8255]={["atomIDs"]={"8255:description:1-83","8255:description:86-171","8255:description:174-247","8255:description:252-326","8255:description:329-442","8255:objective:1-69","8255:objective:72-134"},["editorialVersion"]=2,["endingAtomIDs"]={"8255:completion:1-49","8255:completion:51-127","8255:completion:132-265"},["opening"]="Azshara's coursers resisted Felwood's sickness and left it behind. Ogtinc reluctantly asks for their glands as a restorative ingredient, making necessity sit uneasily beside the Circle's regard for the animals.",["pending"]="{actor} would bring four Healthy Courser Glands.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} supplied the glands for Ogtinc's proposed salve.",["sourceHash"]="1dbb61ff72b30f645241ea9050934bc1a60a776f64a2b78a3bd69a3ceaa78ef8",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[8256]={["atomIDs"]={"8256:description:1-91","8256:description:94-152","8256:description:157-319","8256:description:322-380","8256:description:385-455","8256:objective:1-50","8256:objective:53-115"},["editorialVersion"]=2,["endingAtomIDs"]={"8256:completion:1-90","8256:completion:92-105"},["opening"]="Ogtinc's cure needs a measure of poison as well. Ichor condensed within powerful undead at Eldarath is the potent ingredient, of which only one sample is required.",["pending"]="{actor} would obtain an Ichor of Undeath for Ogtinc.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the unpleasant but necessary ichor.",["sourceHash"]="e690ea7106dec8c9537a507e5017bf15fc08f72313ce7f6b881063b4f2d56db2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
