[8258]={["atomIDs"]={"8258:description:1-72","8258:description:75-159","8258:description:162-218","8258:description:223-335","8258:description:338-397","8258:description:400-421","8258:description:424-488","8258:objective:1-90","8258:objective:93-141","8258:objective:144-221","8258:objective:226-308"},["editorialVersion"]=2,["endingAtomIDs"]={"8258:completion:1-31","8258:completion:33-121","8258:completion:126-224","8258:completion:226-264","8258:completion:269-393"},["opening"]="Sagorne fears Darkreaver's control over the spirit realm from Scholomance's Great Ossuary. The divination scryer can summon his servants and draw the death knight out once they fall.",["pending"]="{actor} would defeat Darkreaver and bring Sagorne his head.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned the head; Sagorne welcomed the victory as hope for the spirit realm's fragile bonds.",["sourceHash"]="83f8f1c3acf71391be929d8d8ba2ea89f279026a9c50ed6a00f4207bab68fbc1",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[8266]={["atomIDs"]={"8266:description:1-83","8266:description:85-168","8266:description:173-302","8266:description:304-382","8266:description:384-425","8266:objective:1-117"},["opening"]="Shatterskull offered recognition even when the Outriders failed to win. Ribbons of sacrifice marked effort on their behalf, acknowledging service without pretending the battle had ended in victory.",["pending"]="{actor} would bring the ribbons to Captain Shatterskull.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} presented the ribbons of sacrifice to Shatterskull.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="6791660cbeb66f03eebcebe3900877c83ba65ad97dcffc716685d1eacb920e76",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVariantNote"]="Source-equivalent commission variants preserve their own IDs, levels and branch masks; wording does not imply distinct canonical events."},
[8267]={["atomIDs"]={"8267:description:1-83","8267:description:85-168","8267:description:173-302","8267:description:304-382","8267:description:384-425","8267:objective:1-117"},["opening"]="Defeat did not erase service to the Outriders. Shatterskull asked that ribbons earned in an unsuccessful trial still be brought to him.",["pending"]="{actor} would seek the Outriders' recognition for the ribbons.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the sacrifice ribbons to Captain Shatterskull.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="76fc9ce3aecdd86a74b40ce6c124ff1b95facb60bfd43b85e4909ea8f80f1ae9",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVariantNote"]="Source-equivalent commission variants preserve their own IDs, levels and branch masks; wording does not imply distinct canonical events."},
[8268]={["atomIDs"]={"8268:description:1-83","8268:description:85-168","8268:description:173-302","8268:description:304-382","8268:description:384-425","8268:objective:1-113"},["opening"]="Farsong allowed for the gulch's reversals. The Sentinels would recognize ribbons from an effort that had not secured victory, valuing the defense even in defeat.",["pending"]="{actor} would take the ribbons of sacrifice to Sentinel Farsong.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} presented the ribbons to Farsong at Silverwing Grove.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="d9be2a95525dfbfa4ab38c802d242cc634480a733943b1cd251186dc4d9f91f9",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVariantNote"]="Source-equivalent commission variants preserve their own IDs, levels and branch masks; wording does not imply distinct canonical events."},
[8269]={["atomIDs"]={"8269:description:1-83","8269:description:85-168","8269:description:173-302","8269:description:304-382","8269:description:384-425","8269:objective:1-113"},["opening"]="The Sentinels' acknowledgment was not reserved for winning fields. Farsong accepted the ribbons carried from a failed effort and encouraged those who had served the cause.",["pending"]="{actor} planned to bring Farsong the sacrifice ribbons.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the ribbons for Silverwing recognition.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="17da8e849399d9ab9493a2eaa6dc00ac755395a63d09128097028262aef71c1d",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVariantNote"]="Source-equivalent commission variants preserve their own IDs, levels and branch masks; wording does not imply distinct canonical events."},
[8275]={["atomIDs"]={"8275:description:1-34","8275:description:37-93","8275:description:96-195","8275:description:202-357","8275:description:362-392","8275:description:395-427","8275:description:429-502","8275:objective:1-58"},["opening"]="Jademoon called Alliance volunteers to Silithus, where Circle forces were gathering against unchecked silithid expansion. Windcaller Proudhorn at Cenarion Hold would give the specific work behind the appeal.",["pending"]="{actor} meant to report to Windcaller Proudhorn.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} spoke with Windcaller Proudhorn at Cenarion Hold.",["sourceClassMask"]="?",["sourceHash"]="2f52ddff2aff03cd003ff5aaddb964233e6cb2acc0aaf336b19aedd2eebf4b84",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[8276]={["aftermath"]="Proudhorn welcomed another answer to the emissaries' call and described ample work ahead.",["atomIDs"]={"8276:description:1-34","8276:description:37-90","8276:description:93-234","8276:description:239-342","8276:description:345-380","8276:description:385-466","8276:description:469-501","8276:objective:1-58"},["endingAtomIDs"]={"8276:completion:1-73","8276:completion:75-103","8276:completion:105-188","8276:completion:190-332"},["opening"]="Blackhoof's call followed tremors and growing hive movements across Azeroth. The Circle was gathering in Silithus to oppose expansion before it went unchallenged any longer.",["pending"]="{actor} meant to report to Proudhorn.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reached Cenarion Hold.",["sourceHash"]="e3e7d570b6df2525e3753f6f3a157f1b11944bfb8420dca27177bdc268c79fce",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[8277]={["aftermath"]="Beetix still hoped the resulting treatment would save Noggle.",["atomIDs"]={"8277:description:1-36","8277:description:39-120","8277:description:123-141","8277:description:144-221","8277:description:226-335","8277:description:340-435","8277:description:438-511","8277:objective:1-125","8277:objective:127-173"},["endingAtomIDs"]={"8277:completion:1-27","8277:completion:30-65"},["opening"]="Beetix had slowed the poison in her herb-gathering cousin but not neutralized it. His northern approach suggested two likely creatures whose venom could supply the first antidote attempt.",["pending"]="{actor} planned to gather eight stingers and eight fangs.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought Beetix the samples.",["sourceHash"]="7dbc3f4442ee3fae210ea9d4acff5d42dd42acb84d5caf133be8fa6e5a40221c",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[8278]={["aftermath"]="The treatment began working and Noggle started to regain consciousness.",["atomIDs"]={"8278:description:1-8","8278:description:11-35","8278:description:38-113","8278:description:118-184","8278:description:187-263","8278:description:266-405","8278:objective:1-151"},["endingAtomIDs"]={"8278:completion:1-4","8278:completion:7-50","8278:completion:53-71"},["opening"]="The first antidote failed. Beetix now suspected stronger southern creatures and needed smaller quantities from a wider range to match the poison threatening her cousin.",["pending"]="{actor} meant to gather samples from all three southern species.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the new stingers and fangs.",["sourceHash"]="6dc277c3cee08471651e5989533a47ebb9c9ded487ba43cdee1564bc0e5d9581",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[8279]={["aftermath"]="Ortell began applying the elaborate substitutions, momentarily questioning their correct order.",["atomIDs"]={"8279:description:1-67","8279:description:70-122","8279:description:125-180","8279:description:185-297","8279:description:300-384","8279:description:387-502","8279:objective:1-78"},["endingAtomIDs"]={"8279:completion:1-4","8279:completion:6-37","8279:completion:40-66","8279:completion:71-129","8279:completion:131-193","8279:completion:196-226"},["opening"]="Ortell's old sect still hunted him. Helping an enemy of the cult offered common cause, but the tablet required a coding book whose three chapters were deliberately kept apart.",["pending"]="{actor} intended to recover all three lexicon chapters.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} supplied Ortell with the chapters.",["sourceHash"]="48178d0e7e69beef60d5d679b3435325a57ceac37f5bb2c4336bf91deded50c4",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[8280]={["atomIDs"]={"8280:description:1-59","8280:description:62-141","8280:description:144-199","8280:description:204-308","8280:description:311-403","8280:description:406-480","8280:objective:1-87"},["opening"]="Proudhorn's confidence in the Hold depended on supplies continuing to arrive. Worms had destroyed a morrowgrain shipment that morning, making caravan protection as urgent as the silithid war.",["pending"]="{actor} planned to confront fifteen dredge strikers.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the supply-line assignment.",["sourceHash"]="7b607b2613b6ff6094796cae19551b7ac214cf96c54ef7b8800ab98bc7fa850e",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[8281]={["atomIDs"]={"8281:description:1-53","8281:description:56-109","8281:description:112-229","8281:description:234-363","8281:objective:1-87"},["opening"]="The northern worms' decline did not guarantee safety. Proudhorn feared larger southern relatives would occupy the gap unless they too were checked.",["pending"]="{actor} meant to confront twenty dredge crushers.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the renewed security assignment.",["sourceHash"]="546490ececbacde5d1fae55c407efa10f32a4608ea40bdc06cb9d7b6806220a9",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[8282]={["aftermath"]="Noggle confirmed that all the rare reagents remained inside.",["atomIDs"]={"8282:description:1-11","8282:description:14-28","8282:description:30-103","8282:description:106-174","8282:description:179-242","8282:description:245-331","8282:description:334-426","8282:description:431-510","8282:objective:1-108"},["endingAtomIDs"]={"8282:completion:1-4","8282:completion:7-34","8282:completion:37-70","8282:completion:73-109"},["opening"]="Noggle remembered dropping his rare reagents while fleeing Deathclasp into a nest of flayers. Still weak after recovery, he needed the satchel back for the Hold's potion supply.",["pending"]="{actor} intended to recover the satchel from the southern mountains.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned Noggle's bag.",["sourceHash"]="d73e31e0dbfc1a2108cb2674a976b296db3a7f2971fc627abb846cc033fdbfa5",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[8283]={["aftermath"]="The captain welcomed access to the mountains as a way around the hives.",["atomIDs"]={"8283:description:1-142","8283:description:145-223","8283:description:226-301","8283:description:304-399","8283:objective:1-62"},["endingAtomIDs"]={"8283:completion:1-10","8283:completion:12-131","8283:completion:133-165"},["opening"]="The bounty placed Deathclasp in the southern mountains after increased hive activity. Her danger to patrols made the pincer proof of more than an isolated hunt.",["pending"]="{actor} planned to recover Deathclasp's pincer.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered it to Kozus.",["sourceHash"]="cc60b421bc16c5a1c0ef96ff15246cdb3d2f9950ac5039227646d4f89a467834",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[8284]={["aftermath"]="She could read words but not coherent meaning and suspected an encoded text.",["atomIDs"]={"8284:description:1-68","8284:description:71-237","8284:description:242-365","8284:description:368-497","8284:objective:1-98"},["endingAtomIDs"]={"8284:completion:1-20","8284:completion:23-122","8284:completion:125-287"},["opening"]="A former cult camp had become a field of elementals and broken debris. Larksbane's recovered clay fragments were too few to reconstruct the record, leaving the site's destruction unexplained.",["pending"]="{actor} meant to gather eight more tablet fragments.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned the fragments to Larksbane.",["sourceHash"]="1ddb9cf3e115fd011cdae8fec32807599aad3312570f0c229c327146ae450136",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[8285]={["aftermath"]="Ortell recognized an opportunity for mutual assistance against his former organization.",["atomIDs"]={"8285:description:1-86","8285:description:89-179","8285:description:182-239","8285:description:244-297","8285:objective:1-54"},["endingAtomIDs"]={"8285:completion:1-47","8285:completion:50-80","8285:completion:87-127","8285:completion:130-181"},["opening"]="Rumor named a deserter hidden in the southern mountains. The repaired tablet was to test whether Ortell's past could unlock what Larksbane's reading could not.",["pending"]="{actor} intended to seek Ortell with the tablet.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought it to the hermit.",["sourceHash"]="1802ae2a132981b7d4e74c0e14de7a7b556faa6aa6dfad669909a6586b5da817",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[8286]={["aftermath"]="Baristolth judged the great one's return the completion of his watch.",["atomIDs"]={"8286:description:1-70","8286:description:72-182","8286:description:187-280","8286:description:285-307","8286:description:309-334","8286:description:336-385","8286:description:387-452","8286:description:454-496","8286:objective:1-81"},["endingAtomIDs"]={"8286:completion:1-48","8286:completion:50-76"},["opening"]="Baristolth recalled being saved and bound as a Watcher by the Bronze. With another war approaching, he needed confirmation that his master had returned before ending his own long watch.",["pending"]="{actor} planned to seek Anachronos at the caverns.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} confirmed the master's presence.",["sourceHash"]="0981d01e8b7707abf57b974b00f497e9709fc01a4b9aad6071850b22f62a7e79",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[8287]={["aftermath"]="Mar'alith accepted the information as new light on the cult's presence and useful guidance for the struggle.",["atomIDs"]={"8287:description:1-18","8287:description:20-70","8287:description:73-128","8287:description:131-187","8287:description:190-204","8287:description:211-267","8287:description:270-358","8287:objective:1-57"},["endingAtomIDs"]={"8287:completion:1-48","8287:completion:51-183","8287:completion:186-230"},["opening"]="Ortell's decoding promised value to the forces gathering against his pursuers. He sent the parchment to their commander, hoping the cult's defeat would finally place him beyond its reach.",["pending"]="{actor} meant to bring the decoded tablet to Mar'alith.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the parchment.",["sourceHash"]="97169d1b6b0a3667a2662d584648ccad2b7c04c2ba65c742936c0d4ebcd11507",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[8288]={["atomIDs"]={"8288:description:1-26","8288:description:28-48","8288:description:50-223","8288:description:228-290","8288:description:292-390","8288:description:392-442","8288:description:444-499","8288:objective:1-108"},["editorialVersion"]=2,["endingAtomIDs"]={"8288:completion:1-81"},["opening"]="Baristolth needs a champion the Bronze Flight can trust with a greater burden. The first proof lies in Blackwing Lair, where Broodlord Lashlayer blocks the way into Nefarian's inner halls.",["pending"]="{actor} would bring Baristolth Lashlayer's head.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the head and completed the first champion's test.",["sourceHash"]="28a5add03e25c53fad0d27e38ace6db5b8b56ab6233ce66f4b9f192b29c01797",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[8290]={["atomIDs"]={"8290:description:1-73","8290:description:75-190","8290:description:195-241","8290:description:243-278","8290:description:283-320","8290:description:323-375","8290:objective:1-135"},["opening"]="Beyond Silverwing Grove, the fight over Ashenvale's timber continued. Farsong wanted the hold defended against the machines and troops consuming the forest.",["pending"]="{actor} would answer Farsong's summons and return a mark.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} presented Farsong with the Warsong mark.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="61fa9e7702e5b57f7b45a14ab0ad1542756a69353f32b3a32e782626810588b4",["sourceRaceMask"]="1101",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVariantNote"]="Source-equivalent commission variants preserve their own IDs, levels and branch masks; wording does not imply distinct canonical events."},
[8291]={["atomIDs"]={"8291:description:1-73","8291:description:75-190","8291:description:195-241","8291:description:243-278","8291:description:283-320","8291:description:323-375","8291:objective:1-135"},["opening"]="Farsong's appeal joined the fate of Silverwing Hold to the forest around it. Opposing the Horde in the gulch would be recognized by a mark brought back to the grove.",["pending"]="{actor} meant to carry a mark to Farsong after service in the gulch.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the requested mark to the Silverwings.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="a3f1b072567a9b75585c0bd91930eeb8c95d708df910250bec88f24ac6496e8c",["sourceRaceMask"]="1101",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVariantNote"]="Source-equivalent commission variants preserve their own IDs, levels and branch masks; wording does not imply distinct canonical events."},
[8292]={["atomIDs"]={"8292:description:1-59","8292:description:61-123","8292:description:125-174","8292:objective:1-107"},["opening"]="The Silverwings offered further trust for the talismans of service. Their acknowledgment looked back to the fighting already undertaken while asking for continued support.",["pending"]="{actor} would present the earned talisman to the Sentinels.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the talisman's presentation at the grove.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="dec9a9831258cd127a178e8dc591eacee56dd3cc9beb3bd129bfcfdd6a055d4f",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVariantNote"]="Source-equivalent commission variants preserve their own IDs, levels and branch masks; wording does not imply distinct canonical events."},
[8293]={["atomIDs"]={"8293:description:1-59","8293:description:61-110","8293:description:112-140","8293:objective:1-100"},["opening"]="The Outriders urged their fighters to keep confronting the Sentinels. A Warsong mark provided the token through which that service could be recognized.",["pending"]="{actor} would bring the earned mark for acknowledgment.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} presented the Warsong mark to the Outriders.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="d6d0be1518b20b5447cd481cbf799c0cffc51c0eba6bf0e3b74b691b50e94c8a",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVariantNote"]="Source-equivalent commission variants preserve their own IDs, levels and branch masks; wording does not imply distinct canonical events."},
[8294]={["atomIDs"]={"8294:description:1-77","8294:description:79-145","8294:description:147-176","8294:description:178-253","8294:description:258-351","8294:description:353-419","8294:description:422-481","8294:objective:1-144"},["opening"]="Shatterskull regarded Ashenvale's timber as the Horde's to take. The Silverwings' attempts to stop the harvest had become a challenge he meant his fighters to answer.",["pending"]="{actor} planned to return a Warsong mark to Captain Shatterskull.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought Shatterskull the requested mark.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="5201a8c3beb33779117294dd05eb007235d635bfcb787c450d87a91bbda0b841",["sourceRaceMask"]="690",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVariantNote"]="Source-equivalent commission variants preserve their own IDs, levels and branch masks; wording does not imply distinct canonical events."},
[8295]={["atomIDs"]={"8295:description:1-77","8295:description:79-145","8295:description:147-176","8295:description:178-253","8295:description:258-351","8295:description:353-419","8295:description:422-481","8295:objective:1-144"},["opening"]="At Mor'shan, the captain's summons put force behind the Horde's claim to the forest. The mark he demanded would stand as evidence of service against the Silverwings.",["pending"]="{actor} would bring a mark from Warsong Gulch to Mor'shan.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} presented the mark to Captain Shatterskull at the camp.",["reviewStatus"]="AUTHOR_REVIEWED_INDEPENDENT_REVIEW_PENDING",["sourceHash"]="8905c6a92815cad39e093f62e61ef43feb433d35e2458e7f4db4ed5cda91c43c",["sourceRaceMask"]="690",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["sourceVariantNote"]="Source-equivalent commission variants preserve their own IDs, levels and branch masks; wording does not imply distinct canonical events."},
