[8299]={["atomIDs"]={"8299:description:1-75","8299:description:78-203","8299:description:206-282","8299:description:287-306","8299:description:309-389","8299:description:392-492","8299:objective:1-114"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["minimumStage"]=2,["objectiveSummary"]="Win in Arathi Basin and bring a resource crate to Mortis at Hammerfall.",["opening"]="Mortis saw the League's expansion from Refuge Pointe as a threat to Horde control. Taking the basin's mines, farmland and workshops would sustain the Defilers while cutting the supplies feeding the Alliance advance.",["pending"]="{actor} would fight for the basin's supplies and carry them to Mortis.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the resource crate to Mortis after victory in Arathi Basin.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="50c1a5e2fb99fe8682f0959e417a3f36a0a72f094caad19d004145cf1cbc28b2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
